-- allocations, transplants ---------------------------------------------
CALL sp_allocate_sample(5, 9);
UPDATE request_sample SET allocation_date = (SELECT request_date + INTERVAL 3 DAY FROM transplant_request WHERE request_id = 5) WHERE request_id = 5 AND sample_id = 9;
CALL sp_allocate_sample(6, 11);
