CALL sp_schedule_transplant(6, CURDATE() + INTERVAL 10 DAY, 'Conditioning regimen starts one week before', @t);
CALL sp_allocate_sample(7, 12);
UPDATE request_sample SET allocation_date = (SELECT request_date + INTERVAL 3 DAY FROM transplant_request WHERE request_id = 7) WHERE request_id = 7 AND sample_id = 12;
CALL sp_schedule_transplant(7, CURDATE() - INTERVAL 75 DAY, 'Myeloablative conditioning', @t);
CALL sp_complete_transplant(@t, 'ENGRAFTED', 'Neutrophil engraftment on day +18');
CALL sp_allocate_sample(8, 13);
UPDATE request_sample SET allocation_date = (SELECT request_date + INTERVAL 3 DAY FROM transplant_request WHERE request_id = 8) WHERE request_id = 8 AND sample_id = 13;
CALL sp_schedule_transplant(8, CURDATE() - INTERVAL 89 DAY, 'Myeloablative conditioning', @t);
CALL sp_complete_transplant(@t, 'COMPLICATIONS', 'Grade II acute GVHD, responding to steroids');

